use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.receive();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let value = match relay.feed.decode(frame: frames[i]) {
            Ok(v) => v,
            Err(_) => 0,
        };
        total = total + value;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

