use harbor.signal;

fn entries() -> String {
    let signals = signal.signals();
    var out = "";
    var i = 0;
    while i < signals.len() {
        if i > 0 {
            out = out.concat(other: ";");
        }
        let text = match signals[i] {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(density) => "fog:".concat(other: density),
        };
        out = out.concat(other: text);
        i = i + 1;
    }
    out
}

